dir=; for x in /etc/mysql/mysql.conf.d /etc/mysql/mariadb.conf.d /etc/mysql/conf.d /etc/my.cnf.d; do [ -d "$x" ] && { dir=$x; break; }; done
[ -n "$dir" ] && printf '[mysqld]\nsql_mode=%s\n' "$new" > "$dir/99-tmaegis-sql_mode.cnf"; true

